    LECTURE_HALL_CSS_B64 = ""  # BUILT
    LECTURE_HALL_CSS = base64.b64decode(LECTURE_HALL_CSS_B64).decode("utf-8")

    INK = "#1D1E21"
    RULE = "#D9D2C2"
    BLUE = "#3959A6"
    RUST = "#B14434"
    PAPER = "#FFFDF7"
    MUTED = "#6A6D75"
    MONO = "ui-monospace,SFMono-Regular,Menlo,Consolas,monospace"
    SANS = "system-ui,-apple-system,'Segoe UI',Roboto,sans-serif"
    WOBBLE = "7px 4px 8px 5px / 5px 8px 4px 7px"

    # ---- words and boxes ------------------------------------------------------

    def note(text, tone=BLUE):
        return mo.Html(
            f'<div style="border-left:3px solid {tone};padding:2px 0 2px 14px;'
            f'margin:14px 0;font-family:{SANS};font-size:16px;color:{INK}">{text}</div>'
        )

    def card(text):
        return mo.Html(
            f'<div style="font-family:{SANS};font-size:15px;color:{MUTED};'
            f'border:1.5px dashed {RULE};border-radius:{WOBBLE};padding:10px 14px;'
            f'display:inline-block">{text}</div>'
        )

    WAITING = card("Waiting on the cells above.")

    def type_me(src):
        """A block of code to read and type. It cannot be selected, so it
        cannot be pasted."""
        return mo.Html(
            f'<pre style="user-select:none;-webkit-user-select:none;cursor:default;'
            f"font-family:{MONO};font-size:13.5px;line-height:1.5;margin:10px 0;"
            f"padding:10px 14px;background:{PAPER};border:1.5px solid {RULE};"
            f'border-radius:{WOBBLE};color:{INK};overflow-x:auto">'
            f"{html.escape(_inspect.cleandoc(src))}</pre>"
        )

    def ask(text, code):
        """A line of words above a block to type."""
        return mo.vstack([mo.md(_inspect.cleandoc(text)), type_me(code)])

    def as_numbers(x, n):
        """x as a float array, or None if it is not n numbers."""
        try:
            a = np.asarray(x, dtype=float)
        except (TypeError, ValueError):
            return None
        return a if a.shape == (n,) else None

    # ---- the network: eleven nodes, four different crowns --------------------
    # Found by search: of all the small connected networks, this is one where
    # the most friends, the shortest distances, the most shortest routes and
    # the settled score game each pick a different node (1, 6, 8 and 4), by a
    # clear margin. The picture is drawn with no crossing lines.
    NET_N = 11
    _NET_EDGES = [
        (0, 1), (1, 2), (1, 3), (1, 4), (2, 5), (3, 7), (4, 5), (4, 6),
        (5, 6), (6, 8), (7, 8), (8, 9), (9, 10),
    ]
    NET_M = len(_NET_EDGES)
    _NET_POS = {
        0: (60, 150), 1: (140, 150), 2: (190, 70), 3: (200, 240), 4: (250, 150),
        5: (280, 70), 6: (340, 110), 7: (350, 240), 8: (410, 150), 9: (470, 100),
        10: (510, 50),
    }

    # The answers, held here so the marking cells never carry them.
    _net = igraph.Graph(n=NET_N, edges=_NET_EDGES)
    NET_TRUTH = {
        "degree": np.array(_net.degree(), dtype=float),
        "avg": np.asarray(_net.distances(), dtype=float).sum(axis=1) / (NET_N - 1),
        "betweenness": np.array(_net.betweenness(), dtype=float),
    }
    _net_A = np.zeros((NET_N, NET_N), dtype=float)
    for _i, _j in _NET_EDGES:
        _net_A[_i, _j] = _net_A[_j, _i] = 1.0

    def net_rounds(k):
        """The score game after k rounds, divided by the biggest each round."""
        c = np.ones(NET_N)
        for _ in range(k):
            c = _net_A @ c
            c = c / c.max()
        return c

    NET_SETTLED = net_rounds(100)

    def order_indices(values):
        """Indices best first, ties broken by position so both sides of a
        comparison agree."""
        v = np.asarray(values, float)
        return list(np.lexsort((np.arange(len(v)), -np.where(np.isfinite(v), v, -np.inf))))

    def net_ready(g):
        """True once the cell above built the network."""
        try:
            if g.vcount() != NET_N or g.ecount() != NET_M:
                return False
            mine = sorted(tuple(sorted(e)) for e in g.get_edgelist())
            return mine == sorted(_NET_EDGES)
        except Exception:
            return False

    def net_missing(g):
        """The first pair a wrong build is missing or inventing."""
        mine = {tuple(sorted(e)) for e in g.get_edgelist()}
        want = {tuple(sorted(e)) for e in _NET_EDGES}
        missing, extra = sorted(want - mine), sorted(mine - want)
        hint = ""
        if missing:
            hint = f"the pair {missing[0][0]}–{missing[0][1]} is missing"
        if extra:
            more = f"{extra[0][0]}–{extra[0][1]} is not in the picture"
            hint = f"{hint}, and {more}" if hint else more
        return hint

    def ok_degree(x):
        v = as_numbers(x, NET_N)
        return v is not None and np.allclose(v, NET_TRUTH["degree"], atol=1e-9)

    def ok_avg(x):
        v = as_numbers(x, NET_N)
        return v is not None and np.allclose(v, NET_TRUTH["avg"], atol=1e-6)

    def ok_betweenness(x):
        v = as_numbers(x, NET_N)
        return v is not None and np.allclose(v, NET_TRUTH["betweenness"], atol=1e-6)

    def ok_settled(x):
        v = as_numbers(x, NET_N)
        return v is not None and (
            np.allclose(v, NET_SETTLED, atol=1e-6)
            or order_indices(v) == order_indices(NET_SETTLED)
        )

    def all_green(g, degree, avg_distance, betweenness, settled):
        if any(x is ... for x in (g, degree, avg_distance, betweenness, settled)):
            return False
        return (
            net_ready(g)
            and ok_degree(degree)
            and ok_avg(avg_distance)
            and ok_betweenness(betweenness)
            and ok_settled(settled)
        )

    # ---- the road map: the empire's roads on a picture of its terrain ---------
    # Roman Road Network (Harvard Dataverse, version 2008). Its points are road
    # junctions, not cities, so tools/build_m06_lab_data.py merges the ones
    # within 150 km of each other into one place and joins two places when a
    # road runs between them: about 300 places. The same tool packs a
    # washed-out OpenTopoMap picture (CC-BY-SA, (c) OpenStreetMap
    # contributors, SRTM) behind them, so nothing is fetched when the
    # notebook opens.
    ROMAN_DATA_B64 = ""  # BUILT-DATA
    _ROMAN = _json.loads(zlib.decompress(base64.b64decode(ROMAN_DATA_B64)))
    _TERRAIN = _ROMAN["terrain"]
    _LONLAT = np.asarray(_ROMAN["nodes"], dtype=float).reshape(-1, 2) / 1000.0
    _ROAD_EDGES = np.asarray(_ROMAN["edges"], dtype=int).reshape(-1, 2)
    ROME = _ROMAN["rome"]  # the place that holds Rome
    ROAD_PLACES = len(_LONLAT)
    ROAD_MERGE_KM = _ROMAN["merge_km"]

    # Scores are asked of the main network only: closeness needs every place to
    # reach every other, and a few outposts are cut off from it.
    _all = igraph.Graph(n=len(_LONLAT), edges=_ROAD_EDGES.tolist())
    _all.simplify()
    _parts = _all.connected_components()
    ROAD_KEEP = np.array(sorted(_parts[int(np.argmax(_parts.sizes()))]))
    ROAD_G = _all.induced_subgraph(ROAD_KEEP, implementation="copy_and_delete")
    ROAD_ROME = int(np.flatnonzero(ROAD_KEEP == ROME)[0])
    ROAD_MEASURES = {
        "degree": np.array(ROAD_G.degree(), dtype=float),
        "closeness": np.array(ROAD_G.closeness(), dtype=float),
        "betweenness": np.array(ROAD_G.betweenness(), dtype=float),
        "eigenvector": np.array(ROAD_G.eigenvector_centrality(), dtype=float),
    }

    # ---- drawing --------------------------------------------------------------
    # No SVG filters here. A hand-drawn wobble (feTurbulence + feDisplacementMap)
    # drew fine locally, but on molab the filter definition is stripped from the
    # output while `filter="url(#...)"` stays, and an SVG element that points at
    # a missing filter is not drawn at all: the nodes' numbers showed and every
    # circle and line vanished.

    def _svg(width, height, body):
        return (
            f'<svg viewBox="0 0 {width} {height}" width="100%" '
            f'style="max-width:{width}px;display:block" '
            f'xmlns="http://www.w3.org/2000/svg">'
            f'<rect x="0" y="0" width="{width}" height="{height}" fill="{PAPER}"/>'
            f'{body}</svg>'
        )

    def _edge_lines(edges, pos, width=2.0, opacity=0.4):
        return "".join(
            f'<line x1="{pos[i][0]:.1f}" y1="{pos[i][1]:.1f}" '
            f'x2="{pos[j][0]:.1f}" y2="{pos[j][1]:.1f}" stroke="{INK}" '
            f'stroke-width="{width}" opacity="{opacity}" stroke-linecap="round"/>'
            for i, j in edges
        )

    def _radii(values, lo, span):
        """Discs from lo to lo + span, the smallest value to the biggest."""
        v = np.asarray(values, float)
        v = np.where(np.isfinite(v), v, 0.0)
        spread = v.max() - v.min()
        return (lo + span * (v - v.min()) / (spread if spread else 1)).tolist()

    def net_svg(values=None, hot=(), fmt="{:g}"):
        """The network, nodes numbered. With `values`, discs are sized by them
        and each number is written above its disc; `hot` nodes are filled."""
        r = [15.0] * NET_N if values is None else _radii(values, 11, 11)
        body = [_edge_lines(_NET_EDGES, _NET_POS)]
        for i in range(NET_N):
            x, y = _NET_POS[i]
            fill = RUST if i in hot else PAPER
            body.append(
                f'<circle cx="{x}" cy="{y}" r="{r[i]:.1f}" fill="{fill}" '
                f'stroke="{INK}" stroke-width="2.2"/>'
            )
        for i in range(NET_N):
            x, y = _NET_POS[i]
            label = PAPER if i in hot else INK
            body.append(
                f'<text x="{x}" y="{y + 4:.0f}" text-anchor="middle" font-size="12" '
                f'font-family="{SANS}" font-weight="700" fill="{label}">{i}</text>'
            )
            if values is not None:
                body.append(
                    f'<text x="{x}" y="{y - r[i] - 6:.0f}" text-anchor="middle" '
                    f'font-family="{MONO}" font-size="12" fill="{RUST}">'
                    f"{fmt.format(values[i])}</text>"
                )
        return _svg(560, 280, "".join(body))

    def _hex(c):
        return np.array([int(c[k:k + 2], 16) for k in (1, 3, 5)], dtype=float)

    def _mix(c1, c2, t):
        r, g, b = (1 - t) * _hex(c1) + t * _hex(c2)
        return f"#{int(r):02x}{int(g):02x}{int(b):02x}"

    def _road_px(lon, lat):
        """Longitude and latitude into the terrain picture (Web Mercator)."""
        size = 256 * 2 ** _TERRAIN["zoom"]
        s = np.sin(np.radians(lat))
        x = (lon + 180.0) / 360.0 * size
        y = (0.5 - np.log((1 + s) / (1 - s)) / (4 * np.pi)) * size
        return x - _TERRAIN["x0"], y - _TERRAIN["y0"]

    _RX, _RY = _road_px(_LONLAT[:, 0], _LONLAT[:, 1])
    _main = np.zeros(len(_LONLAT), dtype=bool)
    _main[ROAD_KEEP] = True
    _segs = np.unique(np.sort(_ROAD_EDGES, axis=1), axis=0)

    def _path(rows):
        return "".join(
            f"M{_RX[a]:.1f} {_RY[a]:.1f}L{_RX[b]:.1f} {_RY[b]:.1f}" for a, b in rows
        )

    _ROAD_MAIN = _path(_segs[_main[_segs[:, 0]] & _main[_segs[:, 1]]])
    _ROAD_REST = _path(_segs[~(_main[_segs[:, 0]] & _main[_segs[:, 1]])])

    def _share_below(v):
        """Each value's place in the ranking, 0 to 1, ties sharing their middle."""
        u, inv, counts = np.unique(v, return_inverse=True, return_counts=True)
        mid = np.cumsum(counts) - (counts - 1) / 2
        return (mid[inv] - 1) / (len(v) - 1)

    def road_svg(values):
        """The roads over the terrain; each place of the main network sized and
        coloured by its score, the best ones ringed, Rome named."""
        W, H = _TERRAIN["w"], _TERRAIN["h"]
        v = np.asarray(values, float)
        q = _share_below(v)
        top = set(np.flatnonzero(np.isclose(v, v.max())).tolist())
        body = [
            f'<image href="data:image/jpeg;base64,{_TERRAIN["jpeg"]}" '
            f'x="0" y="0" width="{W}" height="{H}"/>',
            f'<path d="{_ROAD_REST}" fill="none" stroke="{MUTED}" '
            'stroke-width="1.6" stroke-dasharray="4 4" opacity="0.6"/>',
            f'<path d="{_ROAD_MAIN}" fill="none" stroke="{INK}" '
            'stroke-width="1.7" opacity="0.5"/>',
        ]
        for k in np.argsort(q):
            n = int(ROAD_KEEP[k])
            body.append(
                f'<circle cx="{_RX[n]:.1f}" cy="{_RY[n]:.1f}" '
                f'r="{3.0 + 10 * q[k] ** 5:.1f}" '
                f'fill="{_mix("#BDB8AA", RUST, q[k] ** 2)}" '
                f'stroke="{INK}" stroke-width="1.2"/>'
            )
        for k in top:
            n = int(ROAD_KEEP[k])
            body.append(
                f'<circle cx="{_RX[n]:.1f}" cy="{_RY[n]:.1f}" r="18" fill="none" '
                f'stroke="{INK}" stroke-width="2.4"/>'
            )
        x, y = _RX[ROME], _RY[ROME]
        body.append(
            f'<circle cx="{x:.1f}" cy="{y:.1f}" r="9" fill="none" stroke="{INK}" '
            'stroke-width="1.6"/>'
            f'<text x="{x + 13:.1f}" y="{y + 5:.1f}" font-family="{SANS}" '
            f'font-size="15" font-weight="700" fill="{INK}" stroke="{PAPER}" '
            f'stroke-width="3" paint-order="stroke">Roma</text>'
        )
        return (
            f'<svg viewBox="0 0 {W} {H}" width="100%" style="max-width:820px;'
            f'display:block;border-radius:{WOBBLE}" '
            f'xmlns="http://www.w3.org/2000/svg">{"".join(body)}</svg>'
        )

    def road_caption(values):
        """Where the best place is, and where Rome stands."""
        v = np.asarray(values, float)
        top = np.flatnonzero(np.isclose(v, v.max()))
        lon, lat = _LONLAT[ROAD_KEEP[top[0]]]
        place = f"{lat:.1f}°N, {lon:.1f}°E"
        first = (
            f"The most central place is at {place}."
            if len(top) == 1
            else f"{len(top)} places tie for the top, one of them at {place}."
        )
        rank = int((v > v[ROAD_ROME]).sum()) + 1
        return f"{first} Rome ranks {rank} of {len(v)}."

